const item = $input.first();
const binary = item.binary?.data;
let csvText = '';

if (binary) {
  csvText = Buffer.isBuffer(binary)
    ? binary.toString('utf-8')
    : Buffer.from(binary, 'base64').toString('utf-8');
} else if (item.json?.data) {
  csvText = String(item.json.data);
}

const lines = csvText.split(/\r?\n/);

function slugify(str) { return String(str || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
function cleanText(str) { if (!str) return ''; return String(str).normalize('NFC').trim(); }
function norm(str) { return cleanText(str).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }

function parseCSVLine(line) {
  const fields = [];
  let currentField = '';
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const char = line[i];
    if (char === '"') {
      if (inQuotes && line[i + 1] === '"') { currentField += '"'; i++; }
      else { inQuotes = !inQuotes; }
    } else if (char === ',' && !inQuotes) { fields.push(currentField); currentField = ''; }
    else { currentField += char; }
  }
  fields.push(currentField);
  return fields;
}

function classifyProduct(name, description) {
  const text = norm(name + ' ' + description);
  if (text.match(/bebe|lactancia|biberon|chupete|humidificador|termometro.*digital|vigilabebes|cuna|cambiador/)) return { c: 'bebe', s: 'Puericultura', g: null, t: null };
  if (text.match(/juego|puzzle|construccion|bloques|encajable|apilable|juguete/)) return { c: 'juguetes', s: 'Educativos', g: null, t: null };
  if (text.match(/figura.*animal|animales.*figura|dinosaurio|insecto|granja/)) return { c: 'juguetes', s: 'Figuras', g: null, t: null };
  if (text.match(/coche|vehiculo|tractor|camion|minimobil/)) return { c: 'juguetes', s: 'Vehículos', g: null, t: null };
  if (text.match(/didactico|educativo|matematicas|numeros|letras|aprendizaje/)) return { c: 'material-escolar', s: 'Didáctico', g: null, t: null };
  if (text.match(/manualidades|pintura|plastilina|modelado|arte/)) return { c: 'material-escolar', s: 'Manualidades', g: null, t: null };
  return { c: 'sin-clasificar', s: 'Miniland pendiente', g: null, t: null };
}

const products = [];
for (let i = 2; i < lines.length; i++) {
  const line = lines[i].trim();
  if (!line) continue;
  try {
    const fields = parseCSVLine(line);
    const name = cleanText(fields[42]);
    const price = parseFloat(fields[48]) || 0;
    const ean = cleanText(fields[51]);
    const sku = cleanText(fields[60]);
    const description = cleanText(fields[8]);
    const image = cleanText(fields[21]);
    if (!sku || !name) continue;
    const skuInterno = `M${sku}`;
    const slug = `${slugify(name)}-${slugify(skuInterno)}`;
    const cats = classifyProduct(name, description);
    const imagenes = image ? [`https://minilandgroup.com/pub/media/catalog/product${image}`] : [];
    products.push({ json: { proveedor: 'miniland', ref_proveedor: sku, sku_interno: skuInterno, name, description, precioBase: price, price: price, ean: ean || null, imagenes, slug, stock: 999, categoryId: cats.c, subcategory: cats.s, grupo: cats.g, tipo_producto: cats.t, published: true, activo: true, visible_web: false, marca: 'Miniland' }});
  } catch (err) {}
}
return products;

function roundUp(price) { return Math.ceil(price * 2) / 2; }
function calcularPrecioConMargen(precioBase) {
  const precio = parseFloat(precioBase);
  if (isNaN(precio) || precio <= 0) return { precioBase: 0, precioFinal: 0 };
  let multiplicador;
  if (precio < 50) multiplicador = 1.50;
  else if (precio < 100) multiplicador = 1.47;
  else if (precio < 200) multiplicador = 1.43;
  else if (precio < 400) multiplicador = 1.38;
  else multiplicador = 1.30;
  const precioConMargen = precio * multiplicador;
  return { precioBase: parseFloat(precio.toFixed(2)), precioFinal: roundUp(precioConMargen * 1.21) };
}
const results = [];
for (const item of $input.all()) {
  const precios = calcularPrecioConMargen(item.json.precioBase);
  results.push({ json: { ...item.json, precioBase: precios.precioBase, price: precios.precioFinal }});
}
return results;
